    for (const m of t.matchAll(/(?:^|[^а-я])с\s+(\d{1,2})(?::\d\d)?\s*(?:ч\S*\s*)?до\s+(\d{1,2})/g)) {
      const a = Number(m[1]), b = Number(m[2]), шире = (b > a ? b - a : b + 12 - a) > 3;
      if (шире) for (let q = найдено.length - 1; q >= 0; q--) if (Math.abs(найдено[q].i - m.index) < 6 && найдено[q].с === 'с') найдено.splice(q, 1);
      // «с 8 до 10» — утро, а не 20:00
      if (!шире && a >= 7 && a <= 8 && b > a && b <= 12 && !/^\S*\s+(вечера|дня)/.test(t.slice(m.index + m[0].length))) for (const x of найдено) if (Math.abs(x.i - m.index) < 6 && x.с === 'с' && !x.часть) x.часть = 'утра';
    }
