    const после = (x) => t.slice(x.i, x.i + 34);
    const отказ = (x) => /^\D*\d{1,2}(?:[:.]\d\d)?\s*(?:ч\S*\s*)?(?:,\s*)?(?:я\s+)?(?:уже\s+)?(не\s+(успева|смогу|могу|получ|подход|удобн|выйдет|буду)|занят|никак|рано|поздно|уйду|ухожу|уеду|на\s+работ)/.test(после(x))
      || /(^|[^а-я])не\s+(в|к|после|раньше|позже)\s*$/.test(t.slice(Math.max(0, x.i - 12), x.i + 3).replace(/\d+$/, ''));
    const лучше = (x) => /(лучше|давайте|давай|можно|удобн\S*|подойд\S*|подходит|тогда|перенес\S*\s+на)\s*(в|к|на|часов\s+в)?\s*$/.test(t.slice(Math.max(0, x.i - 18), x.i + 3));
    let кандидаты = найдено.filter((x) => x.h >= 0 && x.h <= 23 && x.часть !== 'ночи' && !отказ(x));
    if (кандидаты.some(лучше)) кандидаты = кандидаты.filter(лучше);
    // «до 18» — срок, не начало; «с 10 до 12» — берём «с 10»
    const годные = кандидаты.sort((a, b) => a.i - b.i);
    if (!годные.length) return null;
    const x = годные[годные.length - 1].с === 'до' ? годные[0] : годные[годные.length - 1];
    let h = x.h;
    if (x.часть === 'вечера' && h < 12) h += 12;
    else if (x.часть === 'дня' && h <= 7) h += 12;
    else if (!x.часть && h >= 1 && h <= 8 && !(x.мин_есть && h < 7 && x.с === '')) h += 12;
    if (h < 7 || h > 22) return null;
