  const НЕ_ДО = new RegExp('(^|[^а-я0-9])(до|после)\\s+(' + ЧАС_ОКНА + ')\\s*,?\\s*' + НЕ_МОГУ_ОКНА, 'g');
  // слова окна — часами; отрицание и «занят до» — в начало / срок. t — текст после текстЧасов (числа цифрами)
  function нормаОкна(t) {
    return занятостьВПосле(String(t || '')
      // «за 2 часа до приезда», «за час до выезда» — когда предупредить, а не окно
      .replace(/(^|[^а-я])за\s+(\d+|пол|полчаса|час|1)\s*(ч\S*|мин\S*)?\s+до(?![а-я])(\s+\S+)?/g, '$1 ')
      .replace(new RegExp('(^|[^а-я])(до|раньше)\\s+обеда\\s*,?\\s*' + НЕ_МОГУ_ОКНА, 'g'), '$1после обеда, ')
      .replace(new RegExp('(^|[^а-я])(после|позже)\\s+обеда\\s*,?\\s*' + НЕ_МОГУ_ОКНА, 'g'), '$1до обеда, ')
      .replace(/(^|[^а-я])до\s+обеда(?![а-я])/g, '$1до 13')
      .replace(/(^|[^а-я])(после|позже)\s+обеда(?![а-я])/g, '$1после 14')
      .replace(/(^|[^а-я])(в|во)\s+перв\S*\s+половин\S*(\s+дня)?(?![а-я])/g, '$1до 13')
      .replace(/(^|[^а-я])(в|во)\s+втор\S*\s+половин\S*(\s+дня)?(?![а-я])/g, '$1после 14')
      .replace(/(^|[^а-я])до\s+полудня(?![а-я])/g, '$1до 12')
      .replace(/(^|[^а-я])между\s+(\d{1,2}(?:[:.]\d\d)?)\s*(?:ч\S*\s*)?и\s+(?=\d)/g, '$1с $2 до ')
      .replace(/(^|[^а-я])не\s+(раньше|ранее)\s+(?=\d)/g, '$1после ')
      .replace(/(^|[^а-я])не\s+(позже|позднее)\s+(?=\d)/g, '$1до ')
      .replace(/(^|[^а-я])(позже|позднее|начиная\s+с|начиная\s+от)\s+(?=\d)/g, '$1после ')
      .replace(/(^|[^а-я])(раньше|ранее|часов\s+до|часам\s+до|часа\s+до)\s+(?=\d)/g, '$1до ')
      .replace(/(^|[^а-я])не\s+(приезжайте|приходите|подъезжайте|надо|нужно|стоит|звоните)\s+до\s+(?=\d)/g, '$1после ')
      .replace(НЕ_ДО, (_m, a, к, ч) => a + (к === 'до' ? 'после ' : 'до ') + ч.trim() + ', '));
  }
