        const деньИз = (y) => { const dy = Date.parse(y.created_at) ? localParts(new Date(Date.parse(y.created_at)), tz).iso : ''; const d2 = dy ? датыСообщения(текстСообщения(y), dy) : []; return d2.length ? d2[d2.length - 1] : ''; };
        for (let j = x.i - 1; !date && j >= 0 && j >= x.i - 6; j--) if (все[j].direction !== 'system') date = деньИз(все[j]);
        for (let j = x.i + 1; !date && j < все.length && j <= x.i + 3; j++) if (все[j].direction === 'out' || все[j].direction === 'note') date = деньИз(все[j]);
