  const ЗА = '(?:(?:\\s+за(?![а-яё])|\\s*/)\\s*(?:м2|м²|кв\\.?\\s?м\\.?|[а-яёa-z]+)(?:\\s+(?!(?:и|а|но|или|в|на|если|при|с|со|без|до|от|по|к|у|не|вас|вам|тоже|также)(?:\\s|$))[а-яё]+){0,2}|\\s+в\\s+(?:час|день|сутки))?';
