  const СТОП_ЦЕНА = new Set(('будет будут стоит стоить стоимость стоимостью стоимости цены цена ценой цене ценам составит обойдется обойдётся выйдет выходит '
    + 'получится получается примерно около где-то это эта этот всё все вам вас у нас меня мне по и а ну так в на за с к о работа работы работу услуга услуги такая '
    + 'такой такие такую данная данный данные обычно начинается начинаются стартует идёт идет смотрите итого всего вместе тут там вопроса районе порядка '
    + 'ориентировочно ориентировочная минимум минимальный минимальная минимальная не меньше дешевле ниже чем ещё еще также тоже я мы вы ты сделаю сделаем '
    + 'поменяю заменю установлю поставлю соберу разберу починю повешу подключу почищу настрою возьму возьмусь беру берём берем прошу ставлю делаю '
    + 'могу можем смогу сможем готов готовы предлагаю для вас вам деньгам чаще если то при цена-то сам сама сами само самого дороже больше максимум пределах давайте ладно хорошо ок извините ошибся ошиблась ой нет поправлюсь прощения опечатка вернее').split(' '));
  const МЕСТОИМЕНИЯ = /^(я|мы|ты)$/;                     // «а я сделаю за 3000», «я ставлю за 1000» — не предмет
  // слово похоже на глагол («сделаю», «будет», «приедет», «повесить», «тянем») — тогда это не предмет цены;
  // частые существительные с такими окончаниями («автомат», «кровать», «стола», «объем», «сохранением») — предмет
  const НЕ_ГЛАГОЛ = /^(автомат|аппарат|агрегат|ламинат|формат|результат|бюджет|пакет|кабинет|предмет|туалет|паркет|шпингалет|гранит|лимит|кредит|объем|подъем|прием|водоем|стола|пола|котла|угла|стекла|масла|сверла|зала|узла|петли|кровать|тетрадь|печать|площадь|сеть|мебель|кровать)$/;
