  const РАБОТА_СЛОВО = /^(чистк|почист|замен|установк|сборк|ремонт|настройк|переустановк|подключени|монтаж|демонтаж|прочистк|заправк|пайк|прошивк|перепрошивк|перевес|перевешивани|врезк|поклейк|укладк|покраск|навес|навеск|вскрыти|регулировк|герметизац|восстановлени|удалени|апгрейд|перенос|разборк|обслуживани|устранени|штукатурк|шпаклевк|сверлени|изготовлени|отделк|перетяжк|смазк|наладк|модернизац|переборк|утеплени|заделк|затирк|окраск|обшивк|поиск|смен|прокладк|штроб|час\b)/i;
