    while (слова.length && СТОП_ЦЕНА.has(low(слова[слова.length - 1]))
      && !(/^(работы|работ|услуги)$/i.test(слова[слова.length - 1]) && слова.length > 1 && /(ие|ые|ий|ый|ой|ая|ое)$/i.test(слова[слова.length - 2]))) слова.pop();
