    const explicit = title.match(/(?:^|[^а-яё])мастер\s+([А-ЯЁ][а-яё]{2,24})(?![а-яё])/i);
    const desc = String(ctx.adDescription || '');
    const named = desc.match(/(?:^|[^а-яё])мастер\s+([А-ЯЁа-яё]{2,24})(?![а-яё])/i);
    const adName = представились([{ direction: 'out', body: desc }]) || (explicit && этоИмя(explicit[1]) ? explicit[1] : '') || (named && этоИмя(named[1]) ? named[1] : '');
    const account = подпись(ctx.accountTitle);
