    const lines = String(comment || '').split('\n').map((s) => s.replace(/^\s*Объявление: «.*?»\.(?: Представились клиенту: [^.\n]+\.)?\s*/, '')).filter((s) => s.trim());
    const at = lines.findIndex((s) => /^Уточнено: |^🟢.*🟢$/.test(s.trim()));
