  // («Какой у вас подъезд?», «Код домофона подскажете?» → «Не надо» — не ответ на вопрос, а отказ; «Встретить у подъезда?» — побочный)
  // «Скидку пенсионерам оформить?», «Пропуск оформить?» — не про заявку
  const ГЛАВНЫЙ_ВОПРОС = /актуальн|мастер\S*\s+(вам\s+)?(еще\s+)?нуж|нуж\S*\s+(ли\s+)?(вам\s+)?(еще\s+)?мастер|заявк|(?<!(скидк|пропуск|документ|чек|гарант|договор|акт)\S*\s+([а-я]+\s+)?)оформ|записать|записыва|вызов|вызыва|ремонт\S*\s+нуж|помощь/;
  const ПРОСИТ = /(^|[^а-я])(нужн[оаы]?|нужен|надо|хочу|хотим|можно|приезжайте|приходите|давайте|жду|ждем|запишите|установить|поставить|подключить|собрать|заменить|починить|отремонтировать|поменять|замените|поменяйте|почините|удобно|подойдет|подходит)(?![а-я])/g;
