  // встречные цены в тексте: [{ at, от, до }] — место слова и границы его фразы
  function встречные(t, цены) {
    const out = [];
    const фразы = предложения(t);
    for (const x of t.matchAll(ВСТРЕЧНАЯ)) {
      const n = /^\d/.test(x[4]) ? Number(x[4]) : 1000;
      if (цены && цены.has(n)) continue;
      const at = x.index + x[1].length;
      const ф = фразы.find((p) => at >= p.at && at < p.at + p.s.length) || { at: 0, s: t };
      out.push({ at, от: ф.at, до: ф.at + ф.s.length });
    }
    return out;
  }
  const ЦЕНА_ОП = /\d+\s*(р|руб|₽|т\.?\s?р|тыс)|от\s*\d{3,}|стоим|бесплатн|выезд|диагност/;
  // и «Надо с мужем посоветоваться», «Пока думаем», «Мы ещё думаем», «Посмотрим» / «Ну посмотрим.» (одно слово решения; «Приезжайте, посмотрим» — нет)
  const ПОДУМАЕТ = /(^|[^а-я])(подума(ю|ем|ть)|надо\s+подумать|посовету(юсь|емся)|посоветоваться|обсуд(им|ить|ю)\s+с\s|не\s+готов[аы]?\s+(пока|сейчас)|пока\s+не\s+готов|(пока|еще)\s+(еще\s+|пока\s+)?дума(ем|ю)(?![а-я])|(?<=(^|[.!?…])\s*)дума(ем|ю)\s+(пока|еще)(?![а-я])|(?<=(^|[.!?…])\s*((ну|ладно|хорошо|ок|ясно|понятно|спасибо)[,.!]?\s*)?)посмотрим(\s+(еще|тогда))?(\s+по\s+(деньгам|финансам|бюджету|цене|ситуации))?(?=\s*([.!…]|$|,?\s*спасибо)))/;
